import{_ as e,b as i,c as o,I as s}from"./chunks/framework.C6cPs9Ia.js";const d=JSON.parse('{"title":"博客搬家史 v3.0：从手写页面到猫窝","description":"柳卿烟博客的三次搬家史——从手写静态页到 VitePress 猫窝主题的完整折腾记录","frontmatter":{"title":"博客搬家史 v3.0：从手写页面到猫窝","date":"2026-09-15T00:00:00.000Z","tags":["建站","折腾","日常"],"pinned":true,"cover":"/LQY/images/moment-3.jpg","head":[["meta",{"name":"description","content":"柳卿烟博客的三次搬家史——从手写静态页到 VitePress 猫窝主题的完整折腾记录"}],["meta",{"name":"keywords","content":"建站, 博客, VitePress, 折腾记录"}]]},"headers":[],"relativePath":"posts/theme-migration.md","filePath":"posts/theme-migration.md"}'),r={name:"posts/theme-migration.md"};function a(n,t,l,u,c,h){return i(),o("div",null,[...t[0]||(t[0]=[s('<p>这个博客已经是<strong>第三代</strong>了。趁今天刚搬进&quot;猫窝&quot;，把三次搬家史整理一下，免得未来的我忘了这一路的坑。</p><hr><h2 id="一代目-手写静态页-纯手工时代的浪漫" tabindex="-1">一代目：手写静态页（纯手工时代的浪漫） <a class="header-anchor" href="#一代目-手写静态页-纯手工时代的浪漫" aria-label="Permalink to &quot;一代目：手写静态页（纯手工时代的浪漫）&quot;">​</a></h2><p>最早的版本是纯 HTML + CSS 手搓的，一个页面一个文件，改个导航要动五个文件。</p><p>现在回头看确实简陋，但那种&quot;这个像素是我亲手挪的&quot;的成就感，之后任何主题都给不了。代码丑但真诚，像个歪歪扭扭的纸箱，但里面装的东西是真的。</p><h2 id="二代目-astro-mizuki-粉色的温柔" tabindex="-1">二代目：Astro + Mizuki（粉色的温柔） <a class="header-anchor" href="#二代目-astro-mizuki-粉色的温柔" aria-label="Permalink to &quot;二代目：Astro + Mizuki（粉色的温柔）&quot;">​</a></h2><p>后来换成了 Astro 的 Mizuki 主题。粉粉的，功能也全：搜索、评论、RSS、暗色模式什么都有。</p><p>用得挺好的。唯一的缺点是……它不是蓝色的。（这个理由自己说出来都觉得离谱，但二次元的事情，你懂的。）</p><h2 id="三代目-vitepress-猫窝-现在这个样子" tabindex="-1">三代目：VitePress + 猫窝（现在这个样子） <a class="header-anchor" href="#三代目-vitepress-猫窝-现在这个样子" aria-label="Permalink to &quot;三代目：VitePress + 猫窝（现在这个样子）&quot;">​</a></h2><p>就是你现在看到的这个。</p><div class="tip custom-block"><p class="custom-block-title">三代目技术清单</p><ul><li><strong>框架</strong>：VitePress 1.6 + Vue 3，SPA 式的页面切换，丝滑</li><li><strong>主题</strong>：深度魔改——我把原来的游戏风主题整个拆了，换成猫羽雫元素，蓝白猫爪配色</li><li><strong>看板娘</strong>：Live2D 猫娘 Shizuku（对，名字都和雫雫的罗马音一样，这真是天意）。亮色模式穿常服，切到暗色模式会换上睡衣，鼠标移过去视线会跟着你走，点她还会说话</li><li><strong>点击特效</strong>：原来的游戏火花特效换成了<strong>猫爪印</strong>，随便点点屏幕试试</li><li><strong>字体</strong>：游戏美术字体 → 霞鹜文楷 Screen，按 unicode 分包按需加载</li><li><strong>背景音乐</strong>：→ 我用 Python 一行行合成出来的原创 8-bit 芯片音乐（对，代码写的歌）</li><li><strong>搜索</strong>：Minisearch 全站全文搜索</li><li><strong>评论</strong>：giscus，GitHub 账号登录即可发言</li><li><strong>部署</strong>：GitHub Pages，全部源码开源在仓库里</li></ul></div><h2 id="搬家过程中踩的坑-仅记录几个典型的" tabindex="-1">搬家过程中踩的坑（仅记录几个典型的） <a class="header-anchor" href="#搬家过程中踩的坑-仅记录几个典型的" aria-label="Permalink to &quot;搬家过程中踩的坑（仅记录几个典型的）&quot;">​</a></h2><ol><li><strong>Live2D 模型自托管</strong>：网上教程基本都是甩个 CDN 链接完事。为了不被第三方 CDN 抽风连累，我把 pixi.js、Cubism2 核心、shizuku 两个形态共 111 个文件全部下到了站点里。5MB 出头，值。</li><li><strong>VitePress 的 base 路径</strong>：部署在 <code>/LQY/</code> 子路径下，所有绝对路径都要小心 base 前缀。看板娘组件里漏写一个前缀，模型就 404 给你看。</li><li><strong>音乐</strong>：原来的 BGM 是某手游的曲子，本命换了之后继续用就不合适了。找不到合适的无版权曲子，最后干脆自己用方波和三角波&quot;画&quot;了一首。Python 的 <code>wave</code> 模块是真好用。</li></ol><h2 id="以后还想加什么" tabindex="-1">以后还想加什么 <a class="header-anchor" href="#以后还想加什么" aria-label="Permalink to &quot;以后还想加什么&quot;">​</a></h2><ul><li>[ ] 深夜模式专属的看板娘闲聊台词（部分完成，还在攒梗）</li><li>[ ] 文章阅读时间估计</li><li>[ ] 一个&quot;猫窝等级&quot;系统，评论越多猫窝越豪华（画大饼阶段）</li></ul><hr><p>总之，欢迎来到三代目。</p><p>博客这条路，一时半会儿是折腾到头了……大概。下次再想折腾的时候，记得先看看月考日程表。</p>',18)])])}const g=e(r,[["render",a]]);export{d as __pageData,g as default};
